  "account.plan.startForFree": { en: "Start for Free", pidgin: "Start for Free", ha: "Fara Kyauta", ig: "Malite n'efu", yo: "Bẹ̀rẹ̀ lọ́fẹ̀ẹ́" },
  "account.plan.footer": { en: "Paid plans are charged instantly from your KudiAI Wallet balance · Cancel anytime", pidgin: "Paid plans dey comot sharp-sharp from your KudiAI Wallet balance · Cancel anytime", ha: "Ana cire kuɗin tsare-tsaren biya nan take daga KudiAI Wallet ɗinka · Soke kowane lokaci", ig: "A na-ewepụ ego atụmatụ akwụ ụgwọ ozugbo na KudiAI Wallet gị · Kagbuo mgbe ọ bụla", yo: "A máa ń yọ owó ètò ìsanwó lẹ́sẹ̀kẹsẹ̀ láti KudiAI Wallet rẹ · Fagilé nígbàkígbà" },
  "account.verify.statusUnverified": { en: "Not verified", pidgin: "Never verify", ha: "Ba a tabbatar ba", ig: "Akwadoghị", yo: "A kò tíì jẹ́rìísí" },
