  "account.verify.statusTier1Pending": { en: "NIN under review", pidgin: "Dem dey check NIN", ha: "Ana duba NIN", ig: "A na-enyocha NIN", yo: "A ń ṣàyẹ̀wò NIN" },
  "account.verify.statusTier1Verified": { en: "Identity verified", pidgin: "Identity don verify", ha: "An tabbatar da shaida", ig: "Akwadola njirimara", yo: "A ti jẹ́rìísí ìdánimọ̀" },
  "account.verify.statusTier2Required": { en: "Enhanced verification required", pidgin: "You need extra verification", ha: "Ana bukatar ƙarin tabbatarwa", ig: "Achọrọ nkwado ka elu", yo: "A nílò ìjẹ́rìísí síwájú sí i" },
  "account.verify.statusTier2Pending": { en: "Under admin review", pidgin: "Admin dey check am", ha: "Admin yana dubawa", ig: "Admin na-enyocha ya", yo: "Admin ń ṣàyẹ̀wò rẹ̀" },
  "account.verify.statusTier2Verified": { en: "Fully verified", pidgin: "Fully verified", ha: "An tabbatar gaba ɗaya", ig: "Akwadola kpamkpam", yo: "A ti jẹ́rìísí pátápátá" },
  "account.verify.statusTier2Rejected": { en: "Documents rejected", pidgin: "Dem reject documents", ha: "An ƙi takardu", ig: "Ajụla akwụkwọ", yo: "A kọ àwọn ìwé" },
  "account.verify.pleaseWait": { en: "Please wait…", pidgin: "Abeg wait…", ha: "Da fatan a jira…", ig: "Biko chere…", yo: "Jọ̀wọ́ dúró…" },
  "account.verify.guarantorN": { en: "Guarantor {n}", pidgin: "Guarantor {n}", ha: "Mai lamuni {n}", ig: "Onye nkwado {n}", yo: "Onígbọ̀wọ́ {n}" },
  "account.verify.fullLegalName": { en: "Full legal name", pidgin: "Full official name", ha: "Cikakken sunan doka", ig: "Aha iwu zuru ezu", yo: "Orúkọ òfin kíkún" },
  "account.verify.phoneNumber": { en: "Phone number", pidgin: "Phone number", ha: "Lambar waya", ig: "Nọmba ekwentị", yo: "Nọ́ńbà fóònù" },
  "account.verify.emailAddress": { en: "Email address", pidgin: "Email address", ha: "Adireshin imel", ig: "Adreesị email", yo: "Àdírẹ́sì email" },
