  "account.help.aiStillNeedHelp": { en: "Still need help? Open a support ticket →", pidgin: "You still need help? Open support ticket →", ha: "Har yanzu kana buƙatar taimako? Buɗe tikitin tallafi →", ig: "Ị ka chọrọ enyemaka? Mepee tiketi nkwado →", yo: "Ṣé o ṣì nílò ìrànlọ́wọ́? Ṣí tíkẹ́ẹ̀tì ìrànlọ́wọ́ →" },
  "account.help.aiNoAnswer": { en: "I couldn't find a specific answer. Please try rephrasing or open a support ticket.", pidgin: "I no see correct answer. Abeg ask am another way or open support ticket.", ha: "Ban sami takamaiman amsa ba. Da fatan ka sake tambaya ta wata hanya ko ka buɗe tikitin tallafi.", ig: "Achọtaghị m azịza doro anya. Biko jụọ ya n'ụzọ ọzọ ma ọ bụ mepee tiketi nkwado.", yo: "Mi ò rí ìdáhùn pàtó. Jọ̀wọ́ béèrè lọ́nà mìíràn tàbí ṣí tíkẹ́ẹ̀tì ìrànlọ́wọ́." },
  "account.help.aiOffline": { en: "I'm having trouble connecting right now. Try again or open a support ticket.", pidgin: "Network dey give me wahala now. Try again or open support ticket.", ha: "Ina samun matsalar haɗi yanzu. Sake gwadawa ko ka buɗe tikitin tallafi.", ig: "Enwere m nsogbu ijikọ ugbu a. Nwaa ọzọ ma ọ bụ mepee tiketi nkwado.", yo: "Mo ní ìṣòro ìsopọ̀ báyìí. Gbìyànjú lẹ́ẹ̀kan sí i tàbí ṣí tíkẹ́ẹ̀tì ìrànlọ́wọ́." },
  "account.help.wasHelpful": { en: "Was this helpful?", pidgin: "This one help you?", ha: "Wannan ya taimaka?", ig: "Nke a ọ bara uru?", yo: "Ṣé èyí ṣèrànwọ́?" },
  "account.help.supportTeam": { en: "Support Team", pidgin: "Support Team", ha: "Ƙungiyar Tallafi", ig: "Ndị Otu Nkwado", yo: "Ẹgbẹ́ Ìrànlọ́wọ́" },
  "account.help.infoNeeded": { en: "Additional info needed", pidgin: "We need more info", ha: "Ana buƙatar ƙarin bayani", ig: "Achọrọ ozi ọzọ", yo: "A nílò àlàyé síi" },
  "account.help.resolution": { en: "Resolution", pidgin: "Solution", ha: "Warwarewa", ig: "Ngwọta", yo: "Ìyanjú" },
  "account.help.rateTitle": { en: "How was our support?", pidgin: "How our support take be?", ha: "Yaya tallafinmu ya kasance?", ig: "Kedu ka nkwado anyị dị?", yo: "Báwo ni ìrànlọ́wọ́ wa ṣe rí?" },
  "account.help.rateSub": { en: "Rate your experience (optional)", pidgin: "Rate how e be for you (if you like)", ha: "Ƙididdige yadda ka ji (na zaɓi)", ig: "Nye ahụmịhe gị akara (nhọrọ)", yo: "Fi ìrírí rẹ ṣe ìdíwọ̀n (àṣàyàn)" },
  "account.help.submitRating": { en: "Submit Rating", pidgin: "Send Rating", ha: "Tura Ƙima", ig: "Zipu Akara", yo: "Fi Ìdíwọ̀n Ránṣẹ́" },
  "account.help.ratingThanks": { en: "Thanks for your rating! ⭐", pidgin: "Thank you for your rating! ⭐", ha: "Mun gode da ƙimarka! ⭐", ig: "Daalụ maka akara gị! ⭐", yo: "A dúpẹ́ fún ìdíwọ̀n rẹ! ⭐" },
  "account.help.reopening": { en: "Reopening…", pidgin: "E dey open again…", ha: "Ana sake buɗewa…", ig: "Na-emeghe ọzọ…", yo: "Ó ń ṣí i padà…" },
  "account.help.reopen": { en: "Reopen Ticket", pidgin: "Open Ticket Again", ha: "Sake Buɗe Tikiti", ig: "Megharịa Tiketi", yo: "Ṣí Tíkẹ́ẹ̀tì Padà" },
