  "account.help.requiredError": { en: "Subject and description are required.", pidgin: "You must put subject and description.", ha: "Ana buƙatar take da bayani.", ig: "Achọrọ isiokwu na nkọwa.", yo: "A nílò àkòrí àti àlàyé." },
  "account.help.newTicketTitle": { en: "New Support Ticket", pidgin: "New Support Ticket", ha: "Sabon Tikitin Tallafi", ig: "Tiketi Nkwado Ọhụrụ", yo: "Tíkẹ́ẹ̀tì Ìrànlọ́wọ́ Tuntun" },
