  "account.help.descriptionPlaceholder": { en: "Describe your issue in detail. Include any error messages or steps to reproduce the problem.", pidgin: "Explain your problem well. Add any error message or wetin you do before e happen.", ha: "Bayyana matsalarka dalla-dalla. Haɗa saƙonnin kuskure ko matakan da suka kai ga matsalar.", ig: "Kọwaa nsogbu gị nke ọma. Tinye ozi njehie ọ bụla ma ọ bụ usoro kpatara nsogbu ahụ.", yo: "Ṣàlàyé ìṣòro rẹ ní kíkún. Fi ọ̀rọ̀ àṣìṣe kankan tàbí ìgbésẹ̀ tó fa ìṣòro náà kún un." },
  "account.help.createNote": { en: "Your ticket will be assigned a reference number and our support team will respond within 24 hours.", pidgin: "Your ticket go get reference number and our support team go reply within 24 hours.", ha: "Za a ba tikitinka lambar shaida kuma ƙungiyar tallafinmu za ta amsa cikin awa 24.", ig: "A ga-enye tiketi gị nọmba ntụaka, ndị otu nkwado anyị ga-aza n'ime awa 24.", yo: "A ó fún tíkẹ́ẹ̀tì rẹ ní nọ́mbà ìtọ́kasí, ẹgbẹ́ ìrànlọ́wọ́ wa yóò sì fèsì láàrin wákàtí 24." },
  "account.help.submitting": { en: "Submitting…", pidgin: "E dey send…", ha: "Ana turawa…", ig: "Na-eziga…", yo: "Ó ń fi ránṣẹ́…" },
  "account.help.submitTicket": { en: "Submit Ticket", pidgin: "Send Ticket", ha: "Tura Tikiti", ig: "Zipu Tiketi", yo: "Fi Tíkẹ́ẹ̀tì Ránṣẹ́" },
  "account.help.searchPlaceholder": { en: "Ask KudiAI anything…", pidgin: "Ask KudiAI anything…", ha: "Tambayi KudiAI komai…", ig: "Jụọ KudiAI ihe ọ bụla…", yo: "Béèrè ohunkóhun lọ́wọ́ KudiAI…" },
  "account.help.all": { en: "All", pidgin: "All", ha: "Duka", ig: "Niile", yo: "Gbogbo" },
