  "account.help.noMatches": { en: "No FAQ matches found — see KudiAI's answer above", pidgin: "No FAQ match am — check KudiAI answer for up", ha: "Ba a sami tambayar da ta dace ba — duba amsar KudiAI a sama", ig: "Ahụghị ajụjụ dabara — lee azịza KudiAI n'elu", yo: "Kò rí ìbéèrè tó bá a mu — wo ìdáhùn KudiAI lókè" },
  "account.help.stillNeedHelp": { en: "Still need help?", pidgin: "You still need help?", ha: "Har yanzu kana buƙatar taimako?", ig: "Ị ka chọrọ enyemaka?", yo: "Ṣé o ṣì nílò ìrànlọ́wọ́?" },
  "account.help.stillNeedHelpBody": { en: "Our support team is ready to help you. Create a ticket and we'll get back to you within 24 hours.", pidgin: "Our support team ready to help you. Create ticket and we go reply you within 24 hours.", ha: "Ƙungiyar tallafinmu a shirye take ta taimake ka. Ƙirƙiri tikiti za mu dawo maka cikin awa 24.", ig: "Ndị otu nkwado anyị dị njikere inyere gị aka. Mepụta tiketi, anyị ga-alọghachikwute gị n'ime awa 24.", yo: "Ẹgbẹ́ ìrànlọ́wọ́ wa ti ṣetán láti ràn ọ́ lọ́wọ́. Ṣẹ̀dá tíkẹ́ẹ̀tì, a ó sì padà sí ọ láàrin wákàtí 24." },
  "account.help.contactSupport": { en: "Contact Support", pidgin: "Contact Support", ha: "Tuntuɓi Tallafi", ig: "Kpọtụrụ Nkwado", yo: "Kàn sí Ìrànlọ́wọ́" },
  "account.help.ticketSubmitted": { en: "Ticket submitted!", pidgin: "Ticket don enter!", ha: "An tura tikiti!", ig: "E zigala tiketi!", yo: "A ti fi tíkẹ́ẹ̀tì ránṣẹ́!" },
  "account.help.referenceLabel": { en: "Reference:", pidgin: "Reference:", ha: "Lambar shaida:", ig: "Ntụaka:", yo: "Ìtọ́kasí:" },
  "account.help.referenceAfter": { en: ". We'll respond within 24 hours.", pidgin: ". We go reply within 24 hours.", ha: ". Za mu amsa cikin awa 24.", ig: ". Anyị ga-aza n'ime awa 24.", yo: ". A ó fèsì láàrin wákàtí 24." },
  "account.help.newTicket": { en: "New Ticket", pidgin: "New Ticket", ha: "Sabon Tikiti", ig: "Tiketi Ọhụrụ", yo: "Tíkẹ́ẹ̀tì Tuntun" },
  "account.help.noTickets": { en: "No tickets yet", pidgin: "No ticket yet", ha: "Babu tikiti tukuna", ig: "Enweghị tiketi ugbu a", yo: "Kò sí tíkẹ́ẹ̀tì síbẹ̀" },
  "account.help.noTicketsSub": { en: "Your support tickets will appear here.", pidgin: "Your support tickets go show here.", ha: "Tikitinka na tallafi za su bayyana a nan.", ig: "Tiketi nkwado gị ga-apụta ebe a.", yo: "Àwọn tíkẹ́ẹ̀tì ìrànlọ́wọ́ rẹ yóò hàn níbí." },
  "account.ticket.requiredError": { en: "Subject and description are required.", pidgin: "You must put subject and description.", ha: "Ana buƙatar take da bayani.", ig: "Achọrọ isiokwu na nkọwa.", yo: "A nílò àkòrí àti àlàyé." },
  "account.ticket.title": { en: "Report an Issue", pidgin: "Report Problem", ha: "Kai Rahoton Matsala", ig: "Kọọ Nsogbu", yo: "Jábọ̀ Ìṣòro" },
  "account.ticket.submittedTitle": { en: "Ticket Submitted", pidgin: "Ticket Don Enter", ha: "An Tura Tikiti", ig: "E Zigala Tiketi", yo: "A Ti Fi Tíkẹ́ẹ̀tì Ránṣẹ́" },
  "account.ticket.submittedBody": { en: "Our support team has received your report and will respond within 24 hours.", pidgin: "Our support team don collect your report, dem go reply you within 24 hours.", ha: "Ƙungiyar tallafinmu ta karɓi rahotonka kuma za ta amsa cikin awa 24.", ig: "Ndị otu nkwado anyị anatala akụkọ gị, ha ga-aza n'ime awa 24.", yo: "Ẹgbẹ́ ìrànlọ́wọ́ wa ti gba ìròyìn rẹ, wọn yóò fèsì láàrin wákàtí 24." },
