  "account.ticket.autoFilled": { en: "(auto-filled — you can add more)", pidgin: "(we don fill am — you fit add more)", ha: "(an cika ta atomatik — za ka iya ƙarawa)", ig: "(ejupụtara ya onwe ya — ị nwere ike tinyekwu)", yo: "(a ti kún un fúnra rẹ̀ — o lè fi kún un)" },
  "account.ticket.refsNote": { en: "Transaction references are included automatically so our team can trace your payment without you having to look them up.", pidgin: "We don add your transaction reference by ourself so our team fit trace your payment — you no need find am.", ha: "An saka lambobin ma'amala kai tsaye don ƙungiyarmu ta bibiyi biyanka ba tare da ka nemo su ba.", ig: "E tinyela nọmba azụmahịa n'onwe ya ka ndị otu anyị wee chọpụta ịkwụ ụgwọ gị n'achọghị ka ị chọọ ha.", yo: "A ti fi nọ́mbà ìdúnàádúrà kún un fúnra rẹ̀ kí ẹgbẹ́ wa lè tọpinpin ìsanwó rẹ láìjẹ́ pé o wá wọn." },
  "account.ticket.submitting": { en: "Submitting…", pidgin: "E dey send…", ha: "Ana turawa…", ig: "Na-eziga…", yo: "Ó ń fi ránṣẹ́…" },
  "account.ticket.submit": { en: "Submit Ticket", pidgin: "Send Ticket", ha: "Tura Tikiti", ig: "Zipu Tiketi", yo: "Fi Tíkẹ́ẹ̀tì Ránṣẹ́" },
  "account.lang.title": { en: "Choose your language", pidgin: "Choose your language", ha: "Zaɓi harshen ku", ig: "Họọ asụsụ gị", yo: "Yan ede rẹ" },
  "account.lang.sub": { en: "You can change this anytime in Settings", pidgin: "You fit change am anytime for Settings", ha: "Za ku iya canza shi a kowane lokaci a Saiti", ig: "Ị nwere ike gbanwee ya n'oge ọ bụla na Ntọala", yo: "O le yipada rẹ ni akoko eyikeyi ni Eto" },
