  "account.ai.chipStaffOverview": { en: "Staff Overview", pidgin: "Staff Overview", ha: "Bayanin Ma'aikata", ig: "Nchịkọta Ndị Ọrụ", yo: "Àkópọ̀ Òṣìṣẹ́" },
