  "account.ai.chipGrowBusiness": { en: "Grow Business", pidgin: "Grow Business", ha: "Bunƙasa Kasuwanci", ig: "Too Azụmaahịa", yo: "Mú Iṣẹ́ Gbèrú" },
  "account.ai.chipAppFeatures": { en: "App Features", pidgin: "Wetin App Fit Do", ha: "Fasalolin Manhaja", ig: "Ihe Ngwa A Na-eme", yo: "Àwọn Ẹ̀yà Áàpù" },
  "account.ai.chipPricingTips": { en: "Pricing Tips", pidgin: "Price Tips", ha: "Shawarwarin Farashi", ig: "Ndụmọdụ Ọnụahịa", yo: "Ìmọ̀ràn Ìdíyelé" },
  "account.ai.greetHello": { en: "Hello! I'm **KudiAI**, your Gemini-powered business assistant.", pidgin: "Hello! I be **KudiAI**, your Gemini business assistant.", ha: "Sannu! Ni ne **KudiAI**, mataimakin kasuwancinku mai amfani da Gemini.", ig: "Nnọọ! Abụ m **KudiAI**, onye inyeaka azụmaahịa gị nke Gemini na-akwado.", yo: "Ẹ n lẹ́ o! Èmi ni **KudiAI**, olùrànlọ́wọ́ iṣẹ́ òwò rẹ tí Gemini ń ṣe agbára rẹ̀." },
  "account.ai.greetData": { en: "I know your real business data — sales, credit, inventory, ajo savings — and I'm here to give you smart, specific advice to help your business grow.", pidgin: "I sabi your real business data — sales, credit, stock, ajo savings — and I dey here to give you correct advice wey go help your business grow.", ha: "Na san ainihin bayanan kasuwancinku — siyarwa, bashi, kaya, ajiyar ajo — kuma ina nan don ba ku shawarwari masu kyau don bunƙasa kasuwancinku.", ig: "Amaara m ezigbo data azụmaahịa gị — ahịa, ụgwọ, ngwaahịa, nchekwa ajo — m nọkwa ebe a inye gị ndụmọdụ doro anya iji too azụmaahịa gị.", yo: "Mo mọ ìwífún gidi iṣẹ́ òwò rẹ — títà, gbèsè, ọjà, ìfowópamọ́ ajo — mo sì wà níbí láti fún ọ ní ìmọ̀ràn tó péye kí iṣẹ́ rẹ lè gbèrú." },
  "account.ai.greetTap": { en: "Tap a quick question below or ask me anything!", pidgin: "Tap any quick question below or ask me anything!", ha: "Danna tambaya a ƙasa ko ka tambaye ni komai!", ig: "Pịa ajụjụ dị n'okpuru ma ọ bụ jụọ m ihe ọ bụla!", yo: "Tẹ ìbéèrè kíákíá nísàlẹ̀ tàbí bi mí ní ohunkóhun!" },
  "account.ai.noResponse": { en: "No response received. Please try again.", pidgin: "No answer come. Abeg try again.", ha: "Ba a sami amsa ba. Da fatan a sake gwadawa.", ig: "Enweghị azịza bịara. Biko nwaa ọzọ.", yo: "Kò sí ìdáhùn kankan. Jọ̀wọ́ gbìyànjú lẹ́ẹ̀kan sí i." },
  "account.ai.poweredBy": { en: "Powered by Gemini · knows your real data", pidgin: "Na Gemini dey power am · e sabi your real data", ha: "Gemini ne ke ƙarfafa shi · ya san ainihin bayananka", ig: "Gemini na-akwado ya · ọ maara ezigbo data gị", yo: "Gemini ló ń ṣe agbára rẹ̀ · ó mọ ìwífún gidi rẹ" },
  "account.ai.businessAssistant": { en: "KudiAI Business Assistant", pidgin: "KudiAI Business Assistant", ha: "Mataimakin Kasuwanci na KudiAI", ig: "Onye Inyeaka Azụmaahịa KudiAI", yo: "Olùrànlọ́wọ́ Òwò KudiAI" },
  "account.ai.muteVoice": { en: "Mute voice replies", pidgin: "Off voice answer", ha: "Kashe amsar murya", ig: "Gbanyụọ azịza olu", yo: "Pa ìdáhùn ohùn" },
  "account.ai.enableVoice": { en: "Enable voice replies", pidgin: "On voice answer", ha: "Kunna amsar murya", ig: "Gbanye azịza olu", yo: "Tan ìdáhùn ohùn" },
  "account.ai.listen": { en: "Listen", pidgin: "Listen", ha: "Saurara", ig: "Gee ntị", yo: "Gbọ́" },
  "account.ai.listeningSpeak": { en: "Listening… speak now", pidgin: "I dey listen… talk now", ha: "Ina saurare… yi magana yanzu", ig: "Ana m ege ntị… kwuo ugbu a", yo: "Mo ń gbọ́… sọ̀rọ̀ báyìí" },
  "account.ai.askBusiness": { en: "Ask anything about your business…", pidgin: "Ask anything about your business…", ha: "Tambayi komai game da kasuwancinka…", ig: "Jụọ ihe ọ bụla gbasara azụmaahịa gị…", yo: "Béèrè ohunkóhun nípa iṣẹ́ òwò rẹ…" },
  "account.ai.listeningStop": { en: "Listening… tap the red button to stop", pidgin: "I dey listen… tap the red button to stop", ha: "Ina saurare… danna maɓallin ja don tsayawa", ig: "Ana m ege ntị… pịa bọtịnụ uhie ka ọ kwụsị", yo: "Mo ń gbọ́… tẹ bọ́tìnnì pupa láti dá dúró" },
  "account.ai.widgetGreetHello": { en: "Welcome! I'm **KudiAI**, your AI business assistant powered by Gemini.", pidgin: "Welcome! I be **KudiAI**, your AI business assistant wey Gemini dey power.", ha: "Barka da zuwa! Ni ne **KudiAI**, mataimakin kasuwancinku na AI mai amfani da Gemini.", ig: "Nnọọ! Abụ m **KudiAI**, onye inyeaka azụmaahịa AI gị nke Gemini na-akwado.", yo: "Ẹ káàbọ̀! Èmi ni **KudiAI**, olùrànlọ́wọ́ òwò AI rẹ tí Gemini ń ṣe agbára rẹ̀." },
  "account.ai.widgetGreetAsk": { en: "Ask me anything about your sales, credit, stock, Ajo savings, staff, or branches — I know your real data!", pidgin: "Ask me anything about your sales, credit, stock, Ajo savings, staff or branches — I sabi your real data!", ha: "Tambaye ni komai game da siyarwa, bashi, kaya, ajiyar Ajo, ma'aikata ko rassanka — na san ainihin bayananka!", ig: "Jụọ m ihe ọ bụla gbasara ahịa, ụgwọ, ngwaahịa, nchekwa Ajo, ndị ọrụ ma ọ bụ alaka gị — amaara m ezigbo data gị!", yo: "Bi mí ní ohunkóhun nípa títà, gbèsè, ọjà, ìfowópamọ́ Ajo, òṣìṣẹ́ tàbí ẹ̀ka rẹ — mo mọ ìwífún gidi rẹ!" },
  "account.ai.loadDataFailed": { en: "Couldn't load your data. Please refresh and try again.", pidgin: "Your data no load. Abeg refresh and try again.", ha: "An kasa loda bayananka. Da fatan a sabunta a sake gwadawa.", ig: "Enweghị ike ibunye data gị. Biko megharịa ma nwaa ọzọ.", yo: "A kò lè gbé ìwífún rẹ wá. Jọ̀wọ́ sọ ọ́ dọ̀tun kí o gbìyànjú lẹ́ẹ̀kan sí i." },
  "account.ai.showAssistant": { en: "Show AI Assistant", pidgin: "Show AI Assistant", ha: "Nuna Mataimakin AI", ig: "Gosi Onye Inyeaka AI", yo: "Fi Olùrànlọ́wọ́ AI hàn" },
  "account.ai.openAssistant": { en: "Open AI Assistant", pidgin: "Open AI Assistant", ha: "Buɗe Mataimakin AI", ig: "Mepee Onye Inyeaka AI", yo: "Ṣí Olùrànlọ́wọ́ AI" },
  "account.ai.hideAiWidget": { en: "Hide AI widget", pidgin: "Hide AI button", ha: "Ɓoye maɓallin AI", ig: "Zoo bọtịnụ AI", yo: "Fi bọ́tìnnì AI pamọ́" },
  "account.ai.widgetTitle": { en: "KudiAI Assistant", pidgin: "KudiAI Assistant", ha: "Mataimakin KudiAI", ig: "Onye Inyeaka KudiAI", yo: "Olùrànlọ́wọ́ KudiAI" },
  "account.ai.hideWidget": { en: "Hide widget", pidgin: "Hide am", ha: "Ɓoye shi", ig: "Zoo ya", yo: "Fi pamọ́" },
