  "account.ai.thinking": { en: "KudiAI is thinking…", pidgin: "KudiAI dey think…", ha: "KudiAI na tunani…", ig: "KudiAI na-eche echiche…", yo: "KudiAI ń ronú…" },
  "account.ai.askAnything": { en: "Ask anything…", pidgin: "Ask anything…", ha: "Tambayi komai…", ig: "Jụọ ihe ọ bụla…", yo: "Béèrè ohunkóhun…" },
  "account.onboarding.photoTooBig": { en: "Photo must be under 5 MB.", pidgin: "Photo must dey under 5 MB.", ha: "Hoton dole ya kasance ƙasa da 5 MB.", ig: "Foto ga-adịrịrị n'okpuru 5 MB.", yo: "Fọ́tò gbọ́dọ̀ kéré sí 5 MB." },
  "account.onboarding.photoRequired": { en: "Please upload a profile photo to continue.", pidgin: "Abeg upload profile photo to continue.", ha: "Da fatan a ɗora hoton bayani don ci gaba.", ig: "Biko bulite foto profaịlụ iji gaa n'ihu.", yo: "Jọ̀wọ́ gbé fọ́tò àkọsílẹ̀ rẹ sókè láti tẹ̀síwájú." },
  "account.onboarding.phoneRequired": { en: "Phone number is required.", pidgin: "You must put phone number.", ha: "Ana buƙatar lambar waya.", ig: "Achọrọ nọmba ekwentị.", yo: "Nọ́mbà fóònù jẹ́ dandan." },
  "account.onboarding.bizNameRequired": { en: "Business name is required.", pidgin: "You must put business name.", ha: "Ana buƙatar sunan kasuwanci.", ig: "Achọrọ aha azụmaahịa.", yo: "Orúkọ iṣẹ́ òwò jẹ́ dandan." },
  "account.onboarding.dbIssue": { en: "Database issue — please sign out and sign back in.", pidgin: "Database get wahala — abeg sign out and sign in back.", ha: "Matsalar rumbun bayanai — da fatan a fita sannan a sake shiga.", ig: "Nsogbu nchekwa data — biko pụọ ma banye ọzọ.", yo: "Ìṣòro ibi ìpamọ́ ìwífún — jọ̀wọ́ jáde kí o tún wọlé." },
  "account.onboarding.photoUploadFailed": { en: "Profile saved! However, your photo couldn't be uploaded — the 'avatars' storage bucket may be missing in Supabase. You can add your photo later in Settings.", pidgin: "Profile don save! But your photo no upload — the 'avatars' storage bucket fit no dey for Supabase. You fit add your photo later for Settings.", ha: "An adana bayanai! Amma ba a iya ɗora hotonka ba — wataƙila ma'ajiyar 'avatars' ba ta cikin Supabase. Za ka iya ƙara hotonka daga baya a Saituna.", ig: "Echekwala profaịlụ! Mana enweghị ike ibulite foto gị — ebe nchekwa 'avatars' nwere ike ọ nọghị na Supabase. Ị nwere ike itinye foto gị ma emechaa na Ntọala.", yo: "A ti fi àkọsílẹ̀ pamọ́! Ṣùgbọ́n a kò lè gbé fọ́tò rẹ sókè — àpò ìpamọ́ 'avatars' lè máà sí nínú Supabase. O lè fi fọ́tò rẹ kún un lẹ́yìn náà nínú Ètò." },
  "account.onboarding.walletActivateFailed": { en: "Could not activate your wallet. Please try again.", pidgin: "Wallet no gree activate. Abeg try again.", ha: "An kasa kunna walat ɗinka. Da fatan a sake gwadawa.", ig: "Enweghị ike ịgbanye obere akpa ego gị. Biko nwaa ọzọ.", yo: "A kò lè mú àpò owó rẹ ṣiṣẹ́. Jọ̀wọ́ gbìyànjú lẹ́ẹ̀kan sí i." },
  "account.onboarding.bvnDigits": { en: "Your BVN must be exactly 11 digits", pidgin: "Your BVN must be exactly 11 digits", ha: "BVN ɗinka dole ya zama lambobi 11 daidai", ig: "BVN gị ga-abụrịrị ọnụọgụ 11 kpọmkwem", yo: "BVN rẹ gbọ́dọ̀ jẹ́ nọ́mbà 11 gẹ́lẹ́" },
  "account.onboarding.ninDigits": { en: "Your NIN must be exactly 11 digits", pidgin: "Your NIN must be exactly 11 digits", ha: "NIN ɗinka dole ya zama lambobi 11 daidai", ig: "NIN gị ga-abụrịrị ọnụọgụ 11 kpọmkwem", yo: "NIN rẹ gbọ́dọ̀ jẹ́ nọ́mbà 11 gẹ́lẹ́" },
