  "account.onboarding.avatarHint": { en: "Your account avatar · up to 5 MB, compressed before upload", pidgin: "Your account picture · reach 5 MB, we go compress am before upload", ha: "Hoton asusunka · har zuwa 5 MB, ana matsa shi kafin ɗorawa", ig: "Foto akaụntụ gị · ruo 5 MB, a na-akpakọ ya tupu ebulite", yo: "Àwòrán àkáǹtì rẹ · tó 5 MB, a ó dín in kù kí a tó gbé e sókè" },
