  "account.onboarding.logoHint": { en: "JPG or PNG · up to 5 MB", pidgin: "JPG or PNG · reach 5 MB", ha: "JPG ko PNG · har zuwa 5 MB", ig: "JPG ma ọ bụ PNG · ruo 5 MB", yo: "JPG tàbí PNG · tó 5 MB" },
