  "account.onboarding.reassurance": { en: "Your address, business type, industry, and more can be filled in from your profile after setup — nothing is lost by skipping them now.", pidgin: "You fit fill your address, business type, industry and others for your profile after setup — nothing go lost if you skip dem now.", ha: "Za ka iya cike adireshinka, nau'in kasuwanci, masana'anta da sauransu daga bayananka bayan saiti — babu abin da zai ɓace idan ka tsallake su yanzu.", ig: "Ị nwere ike idejupụta adreesị gị, ụdị azụmaahịa, ngalaba na ndị ọzọ site na profaịlụ gị mgbe ịhazichara — ọ dịghị ihe na-efu ma ị wụfee ha ugbu a.", yo: "O lè kún àdírẹ́sì rẹ, irú òwò, ẹ̀ka iṣẹ́ àti àwọn mìíràn láti inú àkọsílẹ̀ rẹ lẹ́yìn ìṣètò — kò sí ohun tó máa sọnù tí o bá fò wọ́n báyìí." },
  "account.onboarding.signOutRetry": { en: "Sign Out & Try Again", pidgin: "Sign Out & Try Again", ha: "Fita & Sake Gwadawa", ig: "Pụọ & Nwaa Ọzọ", yo: "Jáde & Gbìyànjú Lẹ́ẹ̀kan Sí I" },
  "account.onboarding.settingUp": { en: "Setting up your account…", pidgin: "We dey set up your account…", ha: "Ana saita asusunka…", ig: "Ana-ahazi akaụntụ gị…", yo: "À ń ṣètò àkáǹtì rẹ…" },
  "account.onboarding.nextOpenWallet": { en: "Next — Open Your Wallet →", pidgin: "Next — Open Your Wallet →", ha: "Gaba — Buɗe Walat ɗinka →", ig: "Ọzọ — Mepee Akpa ego Gị →", yo: "Ìtẹ̀síwájú — Ṣí Àpò owó Rẹ →" },
  "account.onboarding.getStarted": { en: "Get started →", pidgin: "Make we start →", ha: "Fara →", ig: "Malite →", yo: "Bẹ̀rẹ̀ →" },
  "account.onboarding.walletInfo": { en: "Every KudiAI business gets a dedicated bank account number — top up once, then pay bills and send money at low fees (no deposit fee on the Standard and Premium plans). Your BVN or NIN opens the account with our banking partner and verifies your identity (Flutterwave/NIBSS KYC); it isn't stored by KudiAI. The name and date of birth on it must match your profile.", pidgin: "Every KudiAI business dey get im own bank account number — top up once, then pay bills and send money with small charge (no deposit fee for Standard and Premium plans). Your BVN or NIN go open the account with our banking partner and confirm who you be (Flutterwave/NIBSS KYC); KudiAI no dey keep am. The name and date of birth wey dey there must match your profile.", ha: "Kowane kasuwanci a KudiAI yana samun lambar asusun banki ta kansa — ka cika sau ɗaya, sannan ka biya kuɗaɗe ka tura kuɗi da ƙaramin caji (babu kuɗin ajiya a tsare-tsaren Standard da Premium). BVN ko NIN ɗinka yana buɗe asusun tare da abokin hulɗarmu na banki kuma yana tabbatar da kai (Flutterwave/NIBSS KYC); KudiAI ba ya adana shi. Suna da ranar haihuwa da ke kansa dole su yi daidai da bayananka.", ig: "Azụmaahịa ọ bụla na KudiAI na-enweta nọmba akaụntụ ụlọ akụ nke ya — tinye ego otu ugboro, wee kwụọ ụgwọ ma zipu ego n'ọnụ ala (enweghị ụgwọ itinye ego na atụmatụ Standard na Premium). BVN ma ọ bụ NIN gị na-emepe akaụntụ ahụ na onye mmekọ ụlọ akụ anyị ma kwado onye ị bụ (Flutterwave/NIBSS KYC); KudiAI anaghị echekwa ya. Aha na ụbọchị ọmụmụ dị na ya ga-adaba na profaịlụ gị.", yo: "Gbogbo òwò KudiAI ló ń gba nọ́mbà àkáǹtì báńkì tirẹ̀ — fi owó sí i lẹ́ẹ̀kan, lẹ́yìn náà san owó iná kí o sì fi owó ránṣẹ́ pẹ̀lú owó kékeré (kò sí owó ìfowólé lórí ètò Standard àti Premium). BVN tàbí NIN rẹ ló ń ṣí àkáǹtì náà pẹ̀lú alábàáṣiṣẹ́pọ̀ báńkì wa, ó sì ń jẹ́rìí ẹni tí o jẹ́ (Flutterwave/NIBSS KYC); KudiAI kò tọ́jú rẹ̀. Orúkọ àti ọjọ́ ìbí tó wà lórí rẹ̀ gbọ́dọ̀ bá àkọsílẹ̀ rẹ mu." },
  "account.onboarding.enterBvn": { en: "Enter your BVN", pidgin: "Put your BVN", ha: "Shigar da BVN ɗinka", ig: "Tinye BVN gị", yo: "Tẹ BVN rẹ" },
