  "account.onboarding.bvnPh": { en: "11-digit Bank Verification Number", pidgin: "11-digit Bank Verification Number", ha: "Lambar Tabbatar da Banki mai lambobi 11", ig: "Nọmba Nkwenye Ụlọ Akụ nwere ọnụọgụ 11", yo: "Nọ́mbà Ìjẹ́rìísí Báńkì oní-díjítì 11" },
  "account.onboarding.ninPh": { en: "11-digit National Identification Number", pidgin: "11-digit National Identification Number", ha: "Lambar Shaidar Ɗan Ƙasa mai lambobi 11", ig: "Nọmba Njirimara Mba nwere ọnụọgụ 11", yo: "Nọ́mbà Ìdánimọ̀ Orílẹ̀-èdè oní-díjítì 11" },
  "account.onboarding.verifyingWallet": { en: "Verifying & opening your wallet…", pidgin: "We dey check & open your wallet…", ha: "Ana tabbatarwa & buɗe walat ɗinka…", ig: "Ana-enyocha & mepee akpa ego gị…", yo: "À ń ṣàyẹ̀wò & ṣí àpò owó rẹ…" },
  "account.onboarding.openMyWallet": { en: "Open my wallet →", pidgin: "Open my wallet →", ha: "Buɗe walat ɗina →", ig: "Mepee akpa ego m →", yo: "Ṣí àpò owó mi →" },
  "account.onboarding.havingTrouble": { en: "Having trouble? Contact support — your account is already set up, only the wallet step remains.", pidgin: "Wahala dey? Contact support — your account don set already, na only wallet step remain.", ha: "Kana da matsala? Tuntuɓi tallafi — an riga an saita asusunka, matakin walat kawai ya rage.", ig: "Ọ na-esiri gị ike? Kpọtụrụ ndị nkwado — akaụntụ gị adịlarị njikere, naanị nzọụkwụ akpa ego fọdụrụ.", yo: "Ṣé o ní ìṣòro? Kàn sí ìrànlọ́wọ́ — a ti ṣètò àkáǹtì rẹ tán, ìgbésẹ̀ àpò owó nìkan ló kù." },
